Settings.QueryText:
//ВЫБРАТЬ
//	АктВыполненныхРабот.НомерАкта КАК Номер,
//	АктВыполненныхРабот.Дата,
//	АктВыполненныхРабот.ПериодОт,
//	АктВыполненныхРабот.ПериодДо,
//	АктВыполненныхРабот.Ссылка,
//	СМ_ИтогиПоСмете.ПрямЗатраты,
//	ВЫБОР
//		КОГДА АктВыполненныхРабот.ПометкаУдаления
//			ТОГДА 1
//		ИНАЧЕ ВЫБОР
//				КОГДА АктВыполненныхРабот.Проведен
//					ТОГДА 2
//				ИНАЧЕ 0
//			КОНЕЦ
//	КОНЕЦ КАК Картинка
//ИЗ
//	Документ.СМ_АктВыполненныхРабот КАК АктВыполненныхРабот
//		ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.СМ_ИтогиПоСмете КАК СМ_ИтогиПоСмете
//		ПО (СМ_ИтогиПоСмете.Смета = АктВыполненныхРабот.Ссылка)
//			И (СМ_ИтогиПоСмете.Итог = ЗНАЧЕНИЕ(Справочник.СМ_ИтогиПоСмете.ВсегоПоСмете))
//ГДЕ
//	АктВыполненныхРабот.ЛокальнаяСмета = &ЛокальнаяСмета

// ****************************************************	
ВЫБРАТЬ
	АктВыполненныхРабот.НомерАкта КАК Номер,
	АктВыполненныхРабот.Дата,
	АктВыполненныхРабот.ПериодОт,
	АктВыполненныхРабот.ПериодДо,
	АктВыполненныхРабот.Ссылка,
	СУММА(СМ_ИтогиПоГлавам.ТекПрямЗатраты) КАК ТекПрямЗатраты,
	ВЫБОР
		КОГДА АктВыполненныхРабот.ПометкаУдаления
			ТОГДА 1
		ИНАЧЕ ВЫБОР
				КОГДА АктВыполненныхРабот.Проведен
					ТОГДА 2
				ИНАЧЕ 0
			КОНЕЦ
	КОНЕЦ КАК Картинка
ИЗ
	Документ.СМ_АктВыполненныхРабот КАК АктВыполненныхРабот
	ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.СМ_ИтогиПоГлавам КАК СМ_ИтогиПоГлавам
	ПО АктВыполненныхРабот.Ссылка = СМ_ИтогиПоГлавам.Смета И СМ_ИтогиПоГлавам.Итог = &ВидИтога
ГДЕ
	АктВыполненныхРабот.ЛокальнаяСмета = &ЛокальнаяСмета

СГРУППИРОВАТЬ ПО
	АктВыполненныхРабот.НомерАкта,
	АктВыполненныхРабот.Дата,
	АктВыполненныхРабот.ПериодОт,
	АктВыполненныхРабот.ПериодДо,
	АктВыполненныхРабот.Ссылка,
	ВЫБОР
		КОГДА АктВыполненныхРабот.ПометкаУдаления
			ТОГДА 1
		ИНАЧЕ ВЫБОР 
			КОГДА АктВыполненныхРабот.Проведен ТОГДА 2
		ИНАЧЕ 0 КОНЕЦ
	КОНЕЦ
